//\u52A0\u901F\u5EA6\u30BB\u30F3\u30B5\u30FC\u30E9\u30A4\u30D6\u30E9\u30EA\u3092\u8FFD\u52A0\n#include "MMA7660.h"\n//LCD \u30E9\u30A4\u30D6\u30E9\u30EA\u3092\u8FFD\u52A0\n#include <rgb_lcd.h>\n\n\n//\u30D4\u30F3 5 \u306B tiltswitchPin \u3068\u3044\u3046\u540D\u524D\u3092\u5272\u308A\u5F53\u3066\n#define tiltswitchPin 5\n\n//MMA7660 \u52A0\u901F\u5EA6\u30BB\u30F3\u30B5\u30FC\u306B accelemeter \u3068\u3044\u3046\u540D\u524D\u3092\u5272\u308A\u5F53\u3066\nMMA7660 accelemeter;\n//rgb_lcd \u753B\u9762\u306B lcd \u3068\u3044\u3046\u540D\u524D\u3092\u5272\u308A\u5F53\u3066\nrgb_lcd lcd;\n\n//alpha \u306B\u5024 0.5 \u3092\u8A2D\u5B9A\nconst float alpha = 0.5;\n\n//fXg\u3001fYg\u3001fZg \u3092\u5024 0 \u306E double \u578B\u3068\u3057\u3066\u521D\u671F\u5316\ndouble fXg = 0;\ndouble fYg = 0;\ndouble fZg = 0;\n//pitch \u3068 roll \u3092 double \u578B\u3068\u3057\u3066\u521D\u671F\u5316\n\nvoid setup()\n{\n  //\u52A0\u901F\u5EA6\u30BB\u30F3\u30B5\u30FC\u3092\u521D\u671F\u5316\n  accelemeter.init();\n  //LCD \u753B\u9762\u3092\u521D\u671F\u5316\n  //LCD \u306E\u5217\u6570\u3068\u884C\u6570\u3092\u8A2D\u5B9A\n  lcd.begin(16, 2);\n  //tiltswitchPin \u306E pinMode \u3092\u5165\u529B\u306B\u8A2D\u5B9A\n  pinMode(tiltswitchPin, INPUT);\n  //2\u79D2\u5F85\u6A5F\n  delay(2000);\n\n}\nvoid loop()\n{\n  /*\u50BE\u304D\u30B9\u30A4\u30C3\u30C1\u304C\u30AA\u30F3\u306E\u5834\u5408\u306F X\u3001Y\u3001Z\u3001\u30ED\u30FC\u30EB\u3068\u30D4\u30C3\u30C1\u306E\u30C7\u30FC\u30BF\u3092\u8868\u793A\n    \u50BE\u304D\u30B9\u30A4\u30C3\u30C1\u304C\u30AA\u30D5\u306E\u5834\u5408\u306F X\u3001Y\u3001Z \u306E\u52A0\u901F\u5EA6\u30C7\u30FC\u30BF\u3092\u8868\u793A\n  */\n  if (HIGH == digitalRead(tiltswitchPin))\n  {\n    //x\u3001y\u3001z \u3092 int8_t \u578B\u3001pitch \u3068 roll \u3092 double \u578B\u3068\u3057\u3066\u521D\u671F\u5316\n    int8_t x;\n    int8_t y;\n    int8_t z;\n    double roll;\n    double pitch;\n    //\u52A0\u901F\u5EA6\u30BB\u30F3\u30B5\u30FC\u304B\u3089 x\u3001y\u3001z \u306E\u30AA\u30D5\u30BB\u30C3\u30C8\u5024\u3092\u53D6\u5F97\n    accelemeter.getXYZ(&x, &y, &z);\n\n    //\u30CE\u30A4\u30BA\u3092\u6E1B\u3089\u3059\u305F\u3081\u306E\u30ED\u30FC\u30D1\u30B9\u30D5\u30A3\u30EB\u30BF\u30FC\n    fXg = x * alpha + (fXg * (1.0 - alpha));\n    fYg = y * alpha + (fYg * (1.0 - alpha));\n    fZg = z * alpha + (fZg * (1.0 - alpha));\n\n    //\u30ED\u30FC\u30EB\u3068\u30D4\u30C3\u30C1\u306E\u8A08\u7B97\u5F0F\n    roll  = (atan2(-fYg, fZg) * 180.0) / M_PI;\n    pitch = (atan2(fXg, sqrt(fYg * fYg + fZg * fZg)) * 180.0) / M_PI;\n    //LCD \u753B\u9762\u3092\u30EA\u30BB\u30C3\u30C8\n    lcd.clear();\n    //LCD \u30AB\u30FC\u30BD\u30EB\u3092\u5217 0\u3001\u884C 0 \u306B\u8A2D\u5B9A\n    lcd.setCursor(0, 0);\n    //\u30C6\u30AD\u30B9\u30C8 x: \u3092\u8868\u793A\n    lcd.print("x:");\n    //x \u306E\u5024\u3092\u8868\u793A\n    lcd.print(x);\n    //LCD \u30AB\u30FC\u30BD\u30EB\u3092\u5217 5\u3001\u884C 0 \u306B\u8A2D\u5B9A\n    lcd.setCursor(5, 0);\n    //\u30C6\u30AD\u30B9\u30C8 y: \u3092\u8868\u793A\n    lcd.print("y:");\n    //y \u306E\u5024\u3092\u8868\u793A\n    lcd.print(y);\n    //LCD \u30AB\u30FC\u30BD\u30EB\u3092\u5217 10\u3001\u884C 0 \u306B\u8A2D\u5B9A\n    lcd.setCursor(10, 0);\n    //\u30C6\u30AD\u30B9\u30C8 z: \u3092\u8868\u793A\n    lcd.print("z:");\n    //z \u306E\u5024\u3092\u8868\u793A\n    lcd.print(z);\n\n    //LCD \u30AB\u30FC\u30BD\u30EB\u3092\u5217 0\u3001\u884C 1 \u306B\u8A2D\u5B9A\n    lcd.setCursor(0, 1);\n    //\u30C6\u30AD\u30B9\u30C8 R: \u3092\u8868\u793A\n    lcd.print("R:");\n    //\u30ED\u30FC\u30EB\u306E\u5024\u3092\u8868\u793A\n    lcd.print(roll);\n    //LCD \u30AB\u30FC\u30BD\u30EB\u3092\u5217 8\u3001\u884C 1 \u306B\u8A2D\u5B9A\n    lcd.setCursor(8, 1);\n    //\u30C6\u30AD\u30B9\u30C8 P: \u3092\u8868\u793A\n    lcd.print("P:");\n    //\u30D4\u30C3\u30C1\u306E\u5024\u3092\u8868\u793A\n    lcd.print(pitch);\n  } else\n  {\n    //ax\u3001ay\u3001az \u3092 float \u578B\u3068\u3057\u3066\u521D\u671F\u5316\n    float ax, ay, az;\n    //\u52A0\u901F\u5EA6\u30BB\u30F3\u30B5\u30FC\u304B\u3089 ax\u3001ay\u3001az \u306E\u52A0\u901F\u5EA6\u5024\u3092\u53D6\u5F97\n    accelemeter.getAcceleration(&ax, &ay, &az);\n    //LCD \u753B\u9762\u3092\u30EA\u30BB\u30C3\u30C8\n    lcd.clear();\n    //LCD \u30AB\u30FC\u30BD\u30EB\u3092\u5217 0\u3001\u884C 0 \u306B\u8A2D\u5B9A\n    lcd.setCursor(0, 0);\n    //\u30C6\u30AD\u30B9\u30C8 ax: \u3092\u8868\u793A\n    lcd.print("ax:");\n    //ax \u306E\u5024\u3092\u8868\u793A\n    lcd.print(ax);\n    //LCD \u30AB\u30FC\u30BD\u30EB\u3092\u5217 8\u3001\u884C 0 \u306B\u8A2D\u5B9A\n    lcd.setCursor(8, 0);\n    //\u30C6\u30AD\u30B9\u30C8 ay: \u3092\u8868\u793A\n    lcd.print("ay:");\n    //ay \u306E\u5024\u3092\u8868\u793A\n    lcd.print(ay);\n    //LCD \u30AB\u30FC\u30BD\u30EB\u3092\u5217 0\u3001\u884C 1 \u306B\u8A2D\u5B9A\n    lcd.setCursor(0, 1);\n    //\u30C6\u30AD\u30B9\u30C8 az: \u3092\u8868\u793A\n    lcd.print("az:");\n    //az \u306E\u5024\u3092\u8868\u793A\n    lcd.print(az);\n  }\n  //0.5\u79D2\u5F85\u6A5F\n  delay(500);\n}\n\n'})}),"\n",(0,s.jsx)(e.p,{children:"\u30B9\u30C6\u30C3\u30D7 2: Seeeduino Lotus \u306B\u30B3\u30FC\u30C9\u3092\u30A2\u30C3\u30D7\u30ED\u30FC\u30C9\u3059\u308B"}),"\n",(0,s.jsx)(e.p,{children:"\u30B9\u30C6\u30C3\u30D7 3: \u7D50\u679C\u3092\u89B3\u5BDF\u3059\u308B"}),"\n",(0,s.jsx)(e.p,{children:"\u307E\u305A\u3001\u50BE\u304D\u30B9\u30A4\u30C3\u30C1\u304CLCD\u753B\u9762\u306E\u30DA\u30FC\u30B8\u3092\u5909\u66F4\u3057\u3066\u3044\u308B\u304B\u3069\u3046\u304B\u3092\u30C6\u30B9\u30C8\u3057\u3066\u304F\u3060\u3055\u3044\u3002\u305D\u306E\u5F8C\u30013\u8EF8\u52A0\u901F\u5EA6\u30BB\u30F3\u30B5\u30FC\u3092\u56DE\u8EE2\u3055\u305B\u3066\u3001\u56DE\u8EE2\u306B\u5FDC\u3058\u305F\u30C7\u30FC\u30BF\u306E\u5909\u5316\u3092\u89B3\u5BDF\u3057\u30013\u8EF8\u52A0\u901F\u5EA6\u30BB\u30F3\u30B5\u30FC\u306E\u51FA\u529B\u30C7\u30FC\u30BF\u304C\u65B9\u5411\u306B\u95A2\u9023\u3057\u3066\u3044\u308B\u3053\u3068\u3092\u7406\u89E3\u3057\u3066\u304F\u3060\u3055\u3